    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (1-9) which are hard to fill given the input distribution.
    // We apply a non-linear penalty for post_residuals in the range [1, 9].
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_res).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward bins that have high remaining capacity to accommodate future, potentially large items.
    // We use a coupling between current progress and the post_residual to favor Best-Fit 
    // early on, but transition to favoring larger residuals as the stream nears completion.
    let residual_utility = post_res * (1.0 - 0.5 * progress);

    // If there is a next item, penalize bins that cannot fit it after current placement.
    let lookahead_penalty = if next_item_size > 0 && (post_residual < next_item_size) {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Penalize opening new bins unless the current best fit is extremely poor (Best-Fit heuristic).
    // If it's a new bin, apply a threshold based on the mean residual of current bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            0.0
        } else {
            // Only open a new bin if the mean residual of current bins is already quite low
            // or if we are forced to by the fitting_bins_count logic.
            15.0 + (mean_residual * 0.5) + (progress * 10.0)
        }
    } else {
        0.0
    };

    // Final score: minimize this value.
    // We combine the residual utility, fragmentation penalty, and lookahead logic.
    post_res + fragmentation_penalty + lookahead_penalty + new_bin_penalty - residual_utility
}

