pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that are unlikely to fit future items).
    // We penalize residuals in the range (0, 10) exponentially.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 5.0;
    }

    // Lookahead coupling: If next_item_size is large, prioritize bins that can accommodate it.
    // We penalize the current placement if it makes the post_residual too small for the next item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 2.0;
    }

    // Dynamic thresholding based on stream progress:
    // As the stream nears the end, we become more aggressive about filling existing bins
    // to avoid leaving too many bins partially empty.
    let fill_urgency = progress * 20.0;
    score += fill_urgency * (post / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decreases as the number of open bins increases (to encourage consolidation).
    if bin_residual == bin_capacity {
        score += 25.0 - (open_bins_count as f64 * 0.5);
    }

    // If this is the only bin that can fit the item, give it a significant priority boost
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Reward bins that stay close to the global mean residual to promote uniform bin usage.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.1;

    score
}

