pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We heavily penalize large remaining gaps (dead space)
    let mut score = post * post * 0.01;

    // Lookahead logic: if the next item fits into this post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 5.0;
    }

    // Penalty for creating a new bin:
    // If this is an empty bin (new bin candidate), penalize it 
    // unless the fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // Adaptivity: As the stream progresses, favor tighter packing 
    // to avoid leaving too many bins partially filled near the end.
    let tightness_factor = (1.0 - progress) * (mean_residual / 10.0);
    score += tightness_factor;

    // Penalty for having too many open bins already (fragmentation avoidance)
    score += (open_bins_count as f64).powf(1.5) * 0.5;

    // Critical constraint: If this is the only bin that fits the current item, 
    // lower the score to ensure we don't open a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit).
    // We start with post_residual as the baseline score.

    // 2. Harmonic Penalty for "Dead Space" (Residuals < next_item_size).
    // If we leave space too small for the next item, we penalize it heavily.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. New Bin Thresholding:
    // Only open a new bin if the current fit is extremely poor (large residual).
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only prefer a new bin if we have many open bins already or if the 
        // current fitting bins are all "bad" fits (leaving very small gaps).
        if fitting_bins_count > 0 {
            score += 40.0; // High penalty for opening a new bin unnecessarily
        }
    }

    // 4. Harmonic Alignment:
    // Penalize residuals that are not multiples of common small items (10, 20, 25).
    // This encourages "clean" packings.
    let remainder = post_residual % 10;
    if remainder != 0 {
        score += remainder as f64 * 0.8;
    }

    // 5. Lookahead efficiency:
    // If the next item fits perfectly into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        if diff < 10.0 {
            score -= 20.0;
        }
    }

    // 6. Global density awareness:
    // As the stream progresses, prioritize closing bins (lower mean_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
