    // We heavily penalize residuals between 1 and 9, as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Lookahead logic: if we know the next item, prioritize bins that fit both current and next
    if next_item_size > 0 {
        if post_residual >= next_item_size {
