    // Lookahead logic: if the next item fits into the current post_residual, 
    // heavily reward this bin to keep the packing density high.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Global state awareness: if we are early in the stream, favor keeping 
    // bins open. If we are late, be more aggressive about closing bins.
    if fitting_bins_count == 1 && post_residual > 0 {
        // If this is the only bin that fits, prioritize it unless it's very inefficient
        score -= 10.0 * (1.0 - progress);
    }

    // Penalty for opening a new bin: only do it if the existing bins are 
    // inefficient (high mean_residual).
    if bin_residual == bin_capacity {
        // This is a new bin. Only pick if mean_residual is high, meaning existing bins are poor.
        score = 30.0 + (mean_residual * 0.5);
    } else {
        // If the bin is already open, adjust based on how much it deviates from the mean.
        // We want to pack into bins that are already "below average" in fullness.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space; we want to minimize it (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often worse than having 0 residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if the next item is large, prioritize bins that can accommodate it.
    // We penalize bins that leave too little room for a likely upcoming large item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Dynamic thresholding: as we near the end of the stream, prioritize filling existing bins
    // more aggressively to avoid leaving sparse bins open.
    let density_factor = 1.0 - (open_bins_count as f64 / (step_index + 1) as f64).clamp(0.0, 1.0);
    score += (progress * 20.0) * density_factor;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // that decays as the stream progresses, but is modulated by how many bins 
    // could have fit the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        let new_bin_cost = 45.0 - (progress * 15.0);
        // If other bins could fit it, increase the penalty for opening a new one.
        score += new_bin_cost + (fitting_bins_count as f64 * 10.0);
    } else {
        // Reward bins that bring the residual closer to the global mean, 
        // encouraging uniform utilization.
        let deviation = (post_res - mean_residual).abs();
        score -= (deviation * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic Best-Fit with Lookahead Pressure
    // Objective: Minimize post_residual, but heavily penalize leaving small "sliver" residuals
    // that cannot fit subsequent items, while rewarding configurations that align with
    // harmonic capacity fractions (e.g., 1/2, 1/3, 1/4).

    let mut score = post_residual as f64;

    // 1. Penalty for small "dead" residuals (the "Sliver" trap)
    // Residuals < 10 are rarely useful unless they are exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Alignment
    // Prefer bin states that reach common fractions of the capacity (50, 33, 25)
    // This maximizes the probability that future items will fit perfectly.
    let dist_to_50 = (post_residual as i32 - 50).abs() as f64;
    let dist_to_33 = (post_residual as i32 - 33).abs() as f64;
    score -= (50.0 - dist_to_50) * 0.1;
    score -= (33.0 - dist_to_33) * 0.05;

    // 3. Lookahead Sensitivity
    // If the next item is large, favor bins that leave enough room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0; // Heavy penalty for blocking the next item
        } else {
            // Reward bins that have just enough room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 4. Global Density Control
    // If we are deep into the stream, discourage opening new bins unless necessary.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate
        score += 15.0 + (progress * 20.0);

        // If there is only one fitting bin, opening a new one is usually a bad idea
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Encourage using existing bins as the stream progresses
        score -= progress * 5.0;
    }

    // 5. Variance Smoothing
    // Penalize bins that deviate significantly from the mean residual of other bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit typical future items (e.g., < 10)
    // but not exactly zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Perfect Fit Bonus: Strongly reward closing a bin or achieving high density.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 3. Lookahead Sensitivity: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
