    }

    // 4. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Must open a new bin, make it the best option.
        }
    }

    // 5. Global Efficiency: If the current placement makes the bin's residual significantly worse 
    // than the mean of all open bins, penalize it to encourage balancing.
    if post_residual < (mean_residual as u32) {
        score += 5.0;
    }

    // 6. Progression Scaling: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize it heavily unless it's the only option.
    if bin_residual == bin_capacity {
        score += 45.0; 
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 2. Best-fit bias: minimize post_residual, but heavily penalize "dead zones" (small remainders).
    // Remainders between 1 and 9 are often unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // 3. Lookahead matching: reward bins where the post_residual can perfectly or nearly accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the next item
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (25.0 - fit_diff).max(0.0);
        } else {
            // Penalize if the next item won't fit in this bin anymore
            score += 5.0;
        }
    }

    // 4. Global balance: encourage using bins that are already "fuller" than the mean.
    // This keeps the remaining empty bins as empty as possible for future large items.
    if (bin_capacity - bin_residual) as f64 > mean_residual {
        score -= 10.0;
    }

    // 5. Urgency: as we approach the end of the stream, favor closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with lookahead and global pressure
    // 1. Base Score: The post-placement residual (Best-Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space":
    // If the post-residual is too small to fit the smallest expected items (e.g., < 10),
    // but large enough to be wasted, penalize it to favor tighter fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // 3. Lookahead integration:
    // If the next item is large and won't fit in this post-residual, 
    // penalize this bin to save space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Global State/Pressure:
    // If we have many open bins, prioritize filling existing bins (lower score).
    // If we have very few bins, be more selective to avoid fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score -= (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // 5. Handling the "New Bin" candidate:
    // If bin_residual == bin_capacity, this is the New Bin call.
    // We only open a new bin if the current best existing bin is "bad" 
    // (e.g., leaves a high residual or conflicts with the next item).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no other options or if all options are "tight"
        // in a way that hurts future capacity.
        if fitting_bins_count > 0 {
            score += 40.0; 
        } else {
            score -= 10.0;
        }
    }

    // 6. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the mean residual 
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses
    // This forces tighter packing early on, but allows for more flexibility later.
    let dead_space_penalty = (post * post) * (1.0 + progress);

    // Favor bins that leave enough room for the lookahead item (next_item_size)
    // If post < next_item_size, we penalize the bin because it forces an extra bin opening later.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Discourage opening new bins (bin_residual == bin_capacity) unless the current
    // fitting options are extremely poor (i.e., they create high dead space).
    let new_bin_bias = if bin_residual == bin_capacity {
        // High constant to discourage opening new bins unless necessary
        // Reduced as the stream ends to clear out remaining items
        50.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Reward bins that keep the mean residual of the system low.
    // This keeps the "average" bin capacity usage consistent.
    let mean_deviation = (post - mean_residual).abs();

    let score = dead_space_penalty + lookahead_penalty + new_bin_bias + mean_deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // if they cannot accommodate the next_item_size.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 45.0; // Penalty for creating a "dead" gap
        }
    }

    // 2. Best-Fit Logic: Reward bins that become "tight" (post_residual near 0).
    // We use an exponential decay to prioritize near-full bins.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other 
    // option exists or all alternatives are severely inefficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 35.0; // Strong bias against opening new bins prematurely
        }
    }

    // 4. Harmonic Alignment:
    // Favor residuals that align with common divisors of the capacity (e.g., 20, 25, 50).
    // These are statistically more likely to fit future items.
    if post_residual > 0 && (post_residual % 20 == 0 || post_residual % 25 == 0) {
        score -= 5.0;
    }

    // 5. Progression awareness:
    // As the stream nears completion, become more aggressive about filling existing bins
    // to minimize the chance of leaving them partially empty at the end.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    // 6. Mean Residual Coupling:
    // If the current bin's post_residual is significantly worse than the mean, penalize.
    if (post_residual as f64) > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the tightness of the bin (Best-Fit principle)
    let mut score = post_residual as f64;

    // 1. Adaptive Fragmentation Penalty
    // If the residual is too small for the next item, we penalize it more aggressively
    // early in the stream, but relax it later to avoid forced new bins.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let decay = 1.0 - (step_index as f64 / total_items as f64);
        score += 40.0 + (decay * 20.0);
    }

    // 2. Lookahead Synergy
    // If the post_residual is exactly the size of the next item, reward it heavily
    // to create perfect pairings.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // 3. New Bin Gatekeeping
    // Dynamic penalty for opening new bins based on current bin density.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Scale penalty by current load; more open bins increase the cost of a new one.
            score += 32.0 + (open_bins_count as f64 * 0.15);
        }
    } else {
        // Reward existing bins that are becoming efficient, but penalize if they deviate 
        // too far from the global mean residual (prevents "hoarding" small items in one bin).
        if (post_residual as f64) > (mean_residual * 1.2) {
            score += 12.0;
        }
    }

    // 4. Capacity Harmonic Alignment
    // Prioritize residuals that leave space for common item size factors (10, 20, 25, 50).
    // This creates "bins of opportunity" for future fitment.
    if post_residual > 0 {
        if post_residual % 25 == 0 { score -= 8.0; }
        else if post_residual % 20 == 0 { score -= 6.0; }
        else if post_residual % 10 == 0 { score -= 3.0; }
    }

    // 5. Final Stage Compaction
    // As the stream nears completion, prioritize closing gaps regardless of future fit,
    // as the opportunity cost of an empty bin is higher than the benefit of a "perfect" bin.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= (bin_capacity - post_residual) as f64 * 0.8;
    } else {
        // Earlier in the game, prefer smaller residuals to keep bins tight.
        score += (bin_capacity - post_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with a base score weighted by the tightness of the fit.
