    let dev_from_mean = (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += dev_from_mean * 25.0;

    // 4. Progress-Weighted Tightness:
    // As the stream approaches completion, prioritize packing efficiency (minimizing residual)
    // over lookahead flexibility to ensure the final bins are as full as possible.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
