    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Lookahead: Optimized threshold for "tight fit" to preserve capacity for future medium-sized items.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 142.0;
        } else {
            let slack = post_residual - next_item_size;
            score -= (110.0 - (slack as f64 * 0.92)).clamp(0.0, 140.0);
        }
    }

    // 2. Non-linear Utilization: Aggressive penalty for under-utilization, favoring bins > 92% capacity.
    let utilization = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= (utilization.powf(6.8) * 780.0);

    // 3. Adaptive New Bin Gate: Stronger resistance to new bins, scaled by current density.
    if is_new_bin {
        let base_new_bin_cost = 380.0;
        let density_factor = (open_bins_count as f64 / (total_items as f64 / 48.0 + 4.0)).min(2.1);
        score += base_new_bin_cost + (density_factor * 480.0) * (1.5 - progress);
    } else {
        score -= (bin_capacity - bin_residual) as f64 * 1.95;
    }

    // 4. Anti-Fragmentation: Target "dead" slivers (1-8) more aggressively to prevent locking space.
    if post_residual > 0 && post_residual <= 8 {
        score += 720.0 - (post_residual as f64 * 65.0);
    } else if post_residual >= 12 {
        score -= 135.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 5. Variance Control: Penalize deviation from mean_residual to prevent "bin-type" clusters.
    score += (post_residual as f64 - mean_residual).abs() * 5.2;

    // 6. Late-stage Compaction: Final 15% of stream forces tighter packing heuristics.
    if progress > 0.85 {
        if is_new_bin {
            score += 5500.0 * progress.powi(8); 
        } else {
            score -= (bin_capacity - post_residual) as f64 * 95.0;
            if post_residual < 10 { score -= 680.0; }
        }
    }

    // 7. Fitting Bin Density: Reward bins with higher residual flexibility.
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64).powf(1.9) * (42.0 * (1.0 - progress * 0.4));
    }

    // 8. Interaction: Penalize immediate next-step failure.
    if !is_new_bin && next_item_size > 0 && bin_residual < next_item_size {
        score += 340.0;
    }

    // 9. Harmonic Alignment: Reward residuals that align with common item sizes (factors of 4, 5, 8).
    if post_residual != 0 {
        if post_residual % 5 == 0 { score -= 95.0; }
        if post_residual % 4 == 0 { score -= 55.0; }
    }

    score
}

