    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Predictive Lookahead: Enhanced sensitivity to future fit-gaps with aggressive penalty for blocking.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 780.0;
        } else if post_residual == next_item_size {
            score -= 1350.0;
        } else {
            score -= (350.0 - ((post_residual - next_item_size) as f64 * 4.5)).clamp(0.0, 350.0);
        }
    }

    // 2. Non-linear Utilization: Aggressive power law to prioritize near-perfect fits.
    let utilization = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= (utilization.powf(18.2) * 4200.0);

    // 3. Adaptive New Bin Gate: Dynamic thresholding for early vs late packing.
    if is_new_bin {
        let density_factor = (open_bins_count as f64 / (total_items as f64 / 92.0 + 4.8)).min(6.0);
        score += 2100.0 + (density_factor * 2600.0) * (1.0 - progress.powf(0.9));
    } else {
        score -= (bin_capacity - bin_residual) as f64 * 6.0;
    }

    // 4. Anti-Fragmentation: Tightened suppression of "sliver" residuals, specifically 1-16 range.
    if post_residual > 0 && post_residual <= 16 {
        score += 3500.0 - (post_residual as f64 * 190.0);
    } else if post_residual > 16 && post_residual <= 24 {
        score += 500.0;
    } else if post_residual > 24 {
        score -= 850.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 5. Global Mean Coupling: Weighted variance penalty to suppress extreme outliers.
    score += (post_residual as f64 - mean_residual).abs() * (26.0 + progress * 24.0);

    // 6. Late-stage Compaction: Aggressive finalization threshold to maximize bin density.
    if progress > 0.92 {
        if is_new_bin {
            score += 85000.0 * progress.powi(40); 
        } else {
            score -= (bin_capacity - post_residual) as f64 * 1250.0;
            if post_residual < 6 { score -= 8000.0; }
        }
    }

    // 7. Fitting Bin Density Bonus: Dynamic consolidation incentive based on remaining items.
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64).sqrt() * 420.0 * (1.0 - progress.powf(1.2));
    }

    // 8. Lookahead Coupling: Penalty for suboptimal bin choice that creates unfillable voids.
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
        score += 3200.0;
    }

    // 9. Harmonic Alignment: Modular preference for clean sub-capacities to aid future fitting.
    if post_residual != 0 {
        let align = match post_residual % 5 {
            0 if post_residual % 25 == 0 => 820.0,
            0 if post_residual % 20 == 0 => 680.0,
            0 if post_residual % 10 == 0 => 500.0,
            0 => 350.0,
            _ if post_residual % 2 == 0 => 200.0,
            _ => 0.0,
        };
        score -= align;
    }

    score
}

