    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Predictive Lookahead: Tuned sensitivity for near-term item fitting.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 810.0;
        } else if post_residual == next_item_size {
            score -= 1420.0;
        } else {
            score -= (350.0 - ((post_residual - next_item_size) as f64 * 4.2)).clamp(0.0, 350.0);
        }
    }

    // 2. Non-linear Utilization: Enhanced power law for tighter bin packing.
    let utilization = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= (utilization.powf(21.0) * 4800.0);

    // 3. Adaptive New Bin Gate: Stricter gate for open bin proliferation.
    if is_new_bin {
        let density_factor = (open_bins_count as f64 / (total_items as f64 / 94.0 + 5.2)).min(6.2);
        score += 2150.0 + (density_factor * 2800.0) * (1.0 - progress);
    } else {
        score -= (bin_capacity - bin_residual) as f64 * 6.2;
    }

    // 4. Anti-Fragmentation: Refined suppression of "sliver" residuals.
    if post_residual > 0 && post_residual <= 20 {
        score += 4500.0 - (post_residual as f64 * 245.0);
    } else if post_residual > 20 && post_residual <= 28 {
        score += 950.0;
    } else if post_residual > 28 {
        score -= 920.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 5. Global Mean Coupling: Weighted variance penalty to enforce cluster density.
    score += (post_residual as f64 - mean_residual).abs() * (28.0 + progress * 24.0);

    // 6. Late-stage Compaction: Aggressive finalization with exponential decay.
    if progress > 0.92 {
        if is_new_bin {
            score += 88000.0 * progress.powi(48); 
        } else {
            score -= (bin_capacity - post_residual) as f64 * 1400.0;
            if post_residual < 6 { score -= 8500.0; }
        }
    }

    // 7. Fitting Bin Density Bonus: Dynamic consolidation incentive.
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64).sqrt() * 480.0 * (1.0 - progress.powf(0.8));
    }

    // 8. Lookahead Coupling: Increased penalty for fragmentation-prone decisions.
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
        score += 3100.0;
    }

    // 9. Harmonic Alignment: Modular preference for common sub-capacities.
    if post_residual != 0 {
        let align = if post_residual % 25 == 0 { 900.0 }
                    else if post_residual % 20 == 0 { 720.0 }
                    else if post_residual % 10 == 0 { 550.0 }
                    else if post_residual % 5 == 0 { 380.0 }
                    else if post_residual % 2 == 0 { 220.0 }
                    else { 0.0 };
        score -= align;
    }

    score
}

