        } else if post_residual > next_item_size {
            // Reward bins that leave exactly enough room for next_item_size plus a small buffer
            score -= (post_residual as f64 - next_item_size as f64) * 0.2;
        }
    }

    // 3. Pressure management: If this is the last chance to fit an item, prioritize it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 4. New bin thresholding: Make opening a new bin expensive unless the fit is poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins have very little capacity left
        // or if we are early in the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 + (mean_residual * 0.5) - (progress * 20.0);
    }

    // 5. Harmonic Class Logic: Favor residuals that align with larger item chunks (e.g., 25, 33, 50)
    // This helps prevent fragmentation by grouping similar-sized items together.
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Gen 191 mutation: Focus on aggressive fragmentation suppression and dynamic bin-gate calibration.
    let mut score = post_residual as f64 * 2.5;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Predictive Lookahead: Stronger penalty for blocking the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 4200.0 + ((next_item_size - post_residual) as f64 * 110.0);
        } else if post_residual == next_item_size {
            score -= 2200.0;
        } else if post_residual >= next_item_size {
            score -= (500.0 - (post_residual - next_item_size) as f64).max(0.0);
        }
    }

    // 2. Non-linear Utilization: Exponential reward for filling bins to near-capacity
    let utilization = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= (utilization.powf(18.0) * 6500.0);

    // 3. Adaptive New Bin Gate: Stricter gating using residual variance signals
    if is_new_bin {
        let base_penalty = 3500.0;
        let dynamic_penalty = (open_bins_count as f64 * 45.0) + (mean_residual * 15.0);
        score += base_penalty + dynamic_penalty * (1.2 - progress);
    } else {
        // Reward deeper filling in existing bins
        score -= (bin_capacity - bin_residual) as f64 * 8.0;
    }

    // 4. Anti-Fragmentation: Target "sliver" residuals (1-25 range)
    if post_residual > 0 && post_residual <= 25 {
        score += 5500.0 - (post_residual as f64 * 180.0);
    } else if post_residual > 25 && post_residual <= 40 {
        score += 800.0;
    }

    // 5. Global Mean Coupling: Penalize deviation from the historical mean to keep bin states uniform
    score += (post_residual as f64 - mean_residual).abs() * (40.0 + progress * 30.0);

    // 6. Late-stage Compaction: Aggressive finalization to clear remaining items
    if progress > 0.85 {
        if is_new_bin {
            score += 120000.0 * progress.powi(64);
        } else {
            score -= (bin_capacity - post_residual) as f64 * 2200.0;
            if post_residual < 12 { score -= 9500.0; }
        }
    }

    // 7. Fitting Bin Density Bonus: Prioritize bins that have the least room for future fragmentation
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64).sqrt() * 650.0 * (1.0 - progress.powf(0.8));
    }

    // 8. Harmonic Alignment: Modular preference for common sub-capacities to reduce entropy
    let align = match post_residual % 25 {
        0 => 1100.0,
        _ => match post_residual % 20 {
            0 => 850.0,
            _ => match post_residual % 10 {
                0 => 600.0,
                _ => 0.0,
            },
        },
    };
    score -= align;

    score
}
